// First image only: the agreement check needs one clean look, not an album.
const j = $json;
if (!j || !j.job_id) return [];
const path = (j.image_paths || [])[0] || null;
if (!path) return [{ json: { ...j, __no_photo: true } }];
return [{ json: { ...j, __path: path } }];

// Two models, same photo, same prompt. Cross-family on purpose: two Gemma
// models would share blind spots and mistake them for corroboration.
const MODELS = ['google/gemma-4-31b-it', 'google/gemini-2.5-flash-lite'];
const claim = ($('Pick photo').all()[0] || {}).json || {};
const signed = $json && $json.signedURL
  ? 'https://untnrofsnmoyxdidxbdj.supabase.co/storage/v1' + $json.signedURL : null;
if (!signed) return [{ json: { __sign_failed: true, __job_id: claim.job_id } }];

const system = [
  "You identify wristwatches from a single photograph.",
  "You are given NO description. Report only what you can actually see.",
  "",
  "Return ONLY JSON with exactly these keys:",
  '{"brand":string|null,"model":string|null,"reference":string|null,',
  '"dial_color":string|null,',
  '"hour_markers":"BATON"|"ROMAN"|"ARABIC"|"MIXED"|"DIAMOND"|"BAGUETTE"|"NONE"|null,',
  '"bezel":"SMOOTH"|"FLUTED"|"CERAMIC"|"TACHYMETRE"|"DIAMOND"|"BAGUETTE"|"GEM_SET"|"ENGRAVED"|null,',
  '"bracelet":"OYSTER"|"JUBILEE"|"PRESIDENT"|"OYSTERFLEX"|"LEATHER"|"RUBBER"|"INTEGRATED"|"MESH"|null,',
  '"case_metal":"STEEL"|"YELLOW_GOLD"|"WHITE_GOLD"|"ROSE_GOLD"|"TWO_TONE"|"PLATINUM"|"TITANIUM"|"CERAMIC"|null,',
  '"diamonds":"NONE"|"DIAL"|"BEZEL"|"BRACELET"|"BEZEL_AND_DIAL"|"FULL"|null,',
  '"confidence":0-100}',
  "",
  "Rules:",
  "- Use null when you cannot see it. A guess is worse than a null.",
  "- Baguette markers are long rectangular stones, not round ones.",
  "- Fluted bezels have fine vertical grooves. Gem-set bezels have stones.",
  "- Jubilee is five-link, Oyster three-link, President three-link and rounded.",
  "- Blue, black and grey all read near-black in a phone photo. If unsure, null.",
].join("\n");

return MODELS.map((model, idx) => ({ json: {
  __job_id: claim.job_id, __listing_id: claim.listing_id,
  __slot: idx === 0 ? 'a' : 'b', __model: model,
  model, temperature: 0.1, max_tokens: 1200, reasoning: { enabled: false },
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: [
      { type: 'text', text: 'Identify this watch. JSON only. Return ONE object for the main watch in the photo, never a list.' },
      { type: 'image_url', image_url: { url: signed } },
    ] },
  ],
} }));

// Both answers, or it is a failure. A single answer cannot corroborate itself.
const reqs = $('Build two requests').all().map(i => i.json);
if (reqs[0] && reqs[0].__sign_failed) {
  return [{ json: { ok: false, job_id: reqs[0].__job_id, error: 'could not sign photo url' } }];
}
let a = null, b = null; const models = [];
$input.all().forEach((item, i) => {
  const meta = reqs[i] || {};
  let read = null;
  try {
    let txt = item.json?.choices?.[0]?.message?.content || '';
    txt = txt.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
    if (txt) read = JSON.parse(txt);
    // Some models answer with a list when the photo shows several watches:
    // take the first (main) one rather than failing the whole verify.
    if (Array.isArray(read)) read = read[0] || null;
  } catch (e) { read = null; }
  if (meta.__slot === 'b') b = read; else a = read;
  models.push(meta.__model);
});
const job = reqs[0] || {};
if (!a || !b) {
  return [{ json: { ok: false, job_id: job.__job_id,
    error: 'model reply missing or unparseable (' + models.join(', ') + ')' } }];
}
return [{ json: { ok: true, job_id: job.__job_id,
  agreement: { p_listing_id: job.__listing_id, p_a: a, p_b: b, p_models: models } } }];
